+void JointLimitationKusudama3D::set_cones(const Vector<Vector4> &p_cones) {
+	cones.clear();
+	int n = MIN((int)p_cones.size(), MAX_KUSUDAMA_CONES);
+	for (int i = 0; i < n; i++) {
+		cones.push_back(p_cones[i]);
+	}
+	emit_changed();
+}
